    async def create_exporter(
        self,
        *,
        datasource_id: str,
        exported_products: list[str],
        name: str,
        region: str | None = None,
        datadog_destination: ExporterDatadogDestination | None = None,
        otlp_destination: ExporterOTLPDestination | None = None,
        description: str | None = None,
    ) -> Exporter:
        """
        Create a data export

        Create an export to send your metrics/logs from a Scaleway data source to an
        external destination.
        Current supported destination for data exports are Datadog and OTLP endpoints.
        This feature is in Beta phase. During Beta phase, exporter can take up to 30 min
        to be effectively active.

        Args:
            region: The region you want to target
            datasource_id: ID of the data source linked to the data export.
            datadog_destination: Datadog destination configuration for the data export.
                One of datadog_destination, otlp_destination is required.
            otlp_destination: OTLP destination configuration for the data export. One of
                datadog_destination, otlp_destination is required.
            exported_products: The list of products name your data export send to the
                destination. To include all products in your data export, you can use an
                array containing "all" You can retrieve the complete list of product
                names using the `ListProducts` endpoint.
            name: Name of the data export.
            description: Description of the data export.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/cockpit/v1/regions/{region}/exporters",
                region=self._client.region(region),
            ),
            body={
                "datasource_id": datasource_id,
                "datadog_destination": datadog_destination,
                "otlp_destination": otlp_destination,
                "exported_products": exported_products,
                "name": name,
                "description": description,
            },
        )
        return Exporter.model_validate(data)

